<script>
(function() {
  // ---- HEADER SCROLL SHADOW ----
  const header = document.getElementById('header');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 10);
  });

  // ---- MOBILE MENU ----
  const menuBtn = document.getElementById('mobileMenuBtn');
  const navLinks = document.getElementById('navLinks');
  menuBtn.addEventListener('click', () => navLinks.classList.toggle('open'));
  navLinks.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => navLinks.classList.remove('open'));
  });

  // ---- PRODUCT CAROUSEL ----
  const track = document.getElementById('carouselTrack');
  const prevBtn = document.getElementById('carouselPrev');
  const nextBtn = document.getElementById('carouselNext');
  const cards = track.querySelectorAll('.product-card');
  let currentIndex = 0;

  function getCardsPerView() {
    const w = window.innerWidth;
    if (w <= 480) return 1.25;
    if (w <= 768) return 2;
    if (w <= 1024) return 3;
    return 4;
  }

  function getScrollAmount() {
    const cardWidth = cards[0].offsetWidth;
    const gap = 20;
    return cardWidth + gap;
  }

  function updateCarousel(animate) {
    if (animate === false) {
      track.style.transition = 'none';
    } else {
      track.style.transition = 'transform 0.5s cubic-bezier(0.4, 0, 0.2, 1)';
    }
    const offset = currentIndex * getScrollAmount();
    track.style.transform = `translateX(-${offset}px)`;
    updateArrows();
  }

  function updateArrows() {
    const maxIndex = cards.length - getCardsPerView();
    prevBtn.disabled = currentIndex <= 0;
    nextBtn.disabled = currentIndex >= Math.max(0, maxIndex);
  }

  nextBtn.addEventListener('click', () => {
    const maxIndex = cards.length - getCardsPerView();
    if (currentIndex < maxIndex) {
      currentIndex = Math.min(currentIndex + 1, Math.ceil(maxIndex));
      updateCarousel(true);
    }
  });

  prevBtn.addEventListener('click', () => {
    if (currentIndex > 0) {
      currentIndex = Math.max(currentIndex - 1, 0);
      updateCarousel(true);
    }
  });

  // Touch/swipe support
  let touchStartX = 0;
  let touchEndX = 0;
  track.addEventListener('touchstart', e => {
    touchStartX = e.changedTouches[0].screenX;
  }, { passive: true });
  track.addEventListener('touchend', e => {
    touchEndX = e.changedTouches[0].screenX;
    const diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 50) {
      if (diff > 0) nextBtn.click();
      else prevBtn.click();
    }
  });

  window.addEventListener('resize', () => updateCarousel(false));
  updateArrows();

  // ---- STORE LOCATOR ----
  const zipInput = document.getElementById('zipInput');
  const searchBtn = document.getElementById('searchBtn');
  const storeResults = document.getElementById('storeResults');

  function showStores() {
    storeResults.classList.add('visible');
    // Re-trigger animations
    storeResults.querySelectorAll('.store-result-card').forEach(card => {
      card.style.animation = 'none';
      card.offsetHeight;
      card.style.animation = '';
    });
  }

  searchBtn.addEventListener('click', () => {
    if (zipInput.value.trim().length >= 3) {
      showStores();
      setTimeout(() => {
        storeResults.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 100);
    }
  });
  zipInput.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      e.preventDefault();
      searchBtn.click();
    }
  });

  // ---- NEWSLETTER ----
  const newsletterForm = document.getElementById('newsletterForm');
  const newsletterSuccess = document.getElementById('newsletterSuccess');
  newsletterForm.addEventListener('submit', e => {
    e.preventDefault();
    const emailInput = document.getElementById('emailInput');
    if (emailInput.value.trim()) {
      newsletterForm.style.display = 'none';
      newsletterSuccess.classList.add('visible');
    }
  });

  // ---- SMOOTH SCROLL FOR HERO CTAs ----
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        e.preventDefault();
        const headerHeight = header.offsetHeight;
        const targetPosition = target.getBoundingClientRect().top + window.scrollY - headerHeight - 16;
        window.scrollTo({ top: targetPosition, behavior: 'smooth' });
      }
    });
  });
})();
</script>
